require"active_support/core_ext/array/extract_options";require"active_support/core_ext/module/redefine_method";module ActiveSupport;class Deprecation;module MethodWrapper;def deprecate_methods(target_module,*method_names)options=method_names.extract_options!;deprecator=options.delete(:deprecator)||self;method_names+=options.keys;mod=nil;method_names.each do |method_name|message=options[method_name];if target_module.method_defined?(method_name)||target_module.private_method_defined?(method_name);method=target_module.instance_method(method_name);target_module.module_eval do redefine_method(method_name) do |*args,&block|deprecator.deprecation_warning(method_name,message);method.bind_call(self,*args,&block);end;ruby2_keywords(method_name);end;else mod||=Module.new;mod.module_eval do define_method(method_name) do |*args,&block|deprecator.deprecation_warning(method_name,message);super(*args,&block);end;ruby2_keywords(method_name);end;end;end;target_module.prepend(mod) if mod;end;end;end;end
